// Rebuilds site/browser/local/vendor/wllama/ from the npm release of @wllama/wllama (MIT).
// Run: node site/browser/local/vendor/make-vendor.mjs <path to node_modules/@wllama/wllama>
// Written by mistral.local@SovereignWebsite.dinis for Dinis Cruz, 21 November 2026. Code Apache-2.0.
//
// Why: the release creates its two Web Workers from blob: URLs built from strings. This site's pages allow
// only same-origin worker scripts, so this script writes those same strings out as two files served from
// this site, and patches createWorker() in index.js to load them. Nothing else in the library is changed.
import fs from 'node:fs';
import path from 'node:path';
import { pathToFileURL } from 'node:url';

const src = process.argv[2];
if (!src) { console.error('usage: node make-vendor.mjs <node_modules/@wllama/wllama>'); process.exit(1); }
const out = path.join(path.dirname(new URL(import.meta.url).pathname), 'wllama');
fs.mkdirSync(out, { recursive: true });

const pkg = JSON.parse(fs.readFileSync(path.join(src, 'package.json'), 'utf8'));
let js = fs.readFileSync(path.join(src, 'esm/index.js'), 'utf8');

// Read the worker strings by importing a copy of the module with one extra export line.
const tmp = path.join(out, '.tmp-extract.mjs');
fs.writeFileSync(tmp, js + '\nexport const __W = { LLAMA_CPP_WORKER_CODE, WLLAMA_EMSCRIPTEN_CODE, JSPI_STUB, OPFS_UTILS_WORKER_CODE, LIBLLAMA_VERSION };\n');
globalThis.self = globalThis.self || {};
const { __W } = await import(pathToFileURL(tmp).href);
fs.unlinkSync(tmp);

// 1. The llama.cpp worker: the same three parts ProxyToWorker.moduleInit() joins, with RUN_OPTIONS fixed to
//    single thread (GitHub Pages cannot send the headers SharedArrayBuffer needs) and no compat mode.
const head = `// Generated by make-vendor.mjs from @wllama/wllama ${pkg.version} (MIT, see LICENCE), llama.cpp ${__W.LIBLLAMA_VERSION}.
// The same code the library would run from a blob: URL, served from this site instead.
const __P = new URL(self.location.href).searchParams;
const RUN_OPTIONS = { pathConfig: { 'wllama.wasm': new URL('./wllama.wasm', self.location.href).href }, nbThread: 0, compat: false };
`;
const noGpu = 'if (__P.get("nogpu") === "1") { try{Object.defineProperty(WorkerNavigator.prototype,"gpu",{get:()=>({requestAdapter:async()=>null})});}catch(e){} }\n';
const mainModuleCode = (__W.JSPI_STUB + __W.WLLAMA_EMSCRIPTEN_CODE).replace('var Module', 'var ___Module');
const llamaWorker = [head + noGpu, `function wModuleInit() { ${mainModuleCode}; return Module; }`, __W.LLAMA_CPP_WORKER_CODE].join(';\n\n');
fs.writeFileSync(path.join(out, 'llama-worker.js'), llamaWorker);

// 2. The OPFS helper worker, as is.
fs.writeFileSync(path.join(out, 'opfs-worker.js'), `// Generated by make-vendor.mjs from @wllama/wllama ${pkg.version} (MIT, see LICENCE).\n` + __W.OPFS_UTILS_WORKER_CODE);

// 3. index.js with createWorker() pointed at the two files.
const before = /var createWorker = \(workerCode\) => \{[\s\S]*?\n\};/;
if (!before.test(js)) throw new Error('createWorker not found: the release changed, review the patch');
js = js.replace(before, `var createWorker = (workerCode, resources) => {
  // PATCHED by Sovereign Website (make-vendor.mjs): same-origin worker files instead of blob: URLs.
  // These workers run without a CSP of their own: GitHub Pages sends no CSP header and the page's meta policy
  // does not reach workers. Accepted by security.b (review 010) because they are same-origin vendored files
  // and compat mode, which would load code from jsdelivr, is refused here.
  if (workerCode === OPFS_UTILS_WORKER_CODE) return new Worker(new URL("./opfs-worker.js", import.meta.url), { type: "module" });
  if (resources && resources.compat) throw new Error("compat mode is not available on this site");
  const q = resources && resources.noWebGPU ? "?nogpu=1" : "";
  return new Worker(new URL("./llama-worker.js" + q, import.meta.url), { type: "module" });
};`);
const call = 'this.worker = createWorker(completeCode);';
if (!js.includes(call)) throw new Error('worker call site not found');
js = js.replace(call, 'this.worker = createWorker(completeCode, this.resources);');
js = js.replace(/\n\/\/# sourceMappingURL=.*$/m, '');
fs.writeFileSync(path.join(out, 'wllama.js'), `// @wllama/wllama ${pkg.version} (MIT, see LICENCE), patched by make-vendor.mjs: see PATCHES.md.\n` + js);
fs.copyFileSync(path.join(src, 'esm/wasm/wllama.wasm'), path.join(out, 'wllama.wasm'));
fs.copyFileSync(path.join(src, 'LICENCE'), path.join(out, 'LICENCE'));
// 4. A record of what was vendored: sha256 of each file, checked by check-vendor.mjs (security.b, review 010).
const crypto = await import('node:crypto');
const sums = ['wllama.js', 'llama-worker.js', 'opfs-worker.js', 'wllama.wasm', 'LICENCE'].map((f) => crypto.createHash('sha256').update(fs.readFileSync(path.join(out, f))).digest('hex') + '  ' + f);
fs.writeFileSync(path.join(out, 'SHA256SUMS'), sums.join('\n') + '\n');
console.log('wrote', fs.readdirSync(out).join(', '), 'from', pkg.version, __W.LIBLLAMA_VERSION);
